const items = $input.all();
const cfg = $('Config').first().json;
const TARGET_STATUSES = new Set(cfg.target_statuses.map(s => s.toLowerCase()));
const WORKBOOK_YEAR = cfg.workbook_year;
const AGE_DAYS = cfg.age_days;
const cutoffMs = Date.now() - AGE_DAYS * 24 * 60 * 60 * 1000;
const validSheets = cfg.monthly_sheets;

function parseBrazilDate(value) {
  const text = String(value ?? '').trim();
  if (!text) return null;

  const match = text.match(/^(\d{1,2})\/(\d{1,2})(?:\/(\d{4}))?(?:\s+(\d{1,2}):(\d{2})(?::(\d{2}))?)?$/);
  if (!match) return null;

  const day = Number(match[1]);
  const month = Number(match[2]);
  const year = match[3] ? Number(match[3]) : WORKBOOK_YEAR;
  const hour = match[4] ? Number(match[4]) : 0;
  const minute = match[5] ? Number(match[5]) : 0;
  const second = match[6] ? Number(match[6]) : 0;

  if (hour > 23 || minute > 59 || second > 59) return null;

  const calendarCheck = new Date(Date.UTC(year, month - 1, day));
  if (
    calendarCheck.getUTCFullYear() !== year ||
    calendarCheck.getUTCMonth() !== month - 1 ||
    calendarCheck.getUTCDate() !== day
  ) return null;

  const wall = Date.UTC(year, month-1, day, hour, minute, second);
  let stamp = wall;
  for (let i=0; i<3; i++) {
    const p = new Intl.DateTimeFormat('en-GB', {timeZone:cfg.timezone, year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(new Date(stamp)).reduce((a,p)=>(a[p.type]=p.value,a),{});
    stamp += wall - Date.UTC(+p.year,+p.month-1,+p.day,+p.hour,+p.minute,+p.second);
  }
  return stamp;
}

const rowsBySheet = Object.fromEntries(validSheets.map(sheet => [sheet, []]));
const ignoredInvalidDateRows = [];

for (const item of items) {
  const row = item.json || {};
  const sheet = String(row._cleanup_sheet || '').trim();
  if (!validSheets.includes(sheet)) continue;

  const rowNumber = Number(row.row_number ?? row.rowNumber ?? row['Row Number']);
  if (!Number.isInteger(rowNumber) || rowNumber < 2) continue;

  const status = String(row.Status ?? row.status ?? '').trim().toLowerCase();
  if (!TARGET_STATUSES.has(status)) continue;

  const dateText = String(
    row['Date Scraped'] ??
    row.date_scraped ??
    row['Date scraped'] ??
    ''
  ).trim();

  const scrapedAtMs = parseBrazilDate(dateText);

  if (scrapedAtMs === null) {
    ignoredInvalidDateRows.push({
      sheet,
      row: rowNumber,
      status: row.Status ?? row.status ?? '',
      date_scraped: dateText,
    });
    continue;
  }

  if (scrapedAtMs <= cutoffMs) rowsBySheet[sheet].push(rowNumber);
}

const blocks = [];
const bySheet = {};

for (const sheet of validSheets) {
  const rows = [...new Set(rowsBySheet[sheet])].sort((a, b) => b - a);
  bySheet[sheet] = rows.length;
  if (!rows.length) continue;

  let high = rows[0];
  let low = rows[0];

  const addBlock = () => {
    blocks.push({
      sheet_name: sheet,
      start_row: low,
      number_to_delete: high - low + 1,
      rows: { from: low, to: high },
    });
  };

  for (let index = 1; index < rows.length; index++) {
    const rowNumber = rows[index];

    if (rowNumber === low - 1) {
      low = rowNumber;
    } else {
      addBlock();
      high = rowNumber;
      low = rowNumber;
    }
  }

  addBlock();
}

const matchedRows = Object.values(bySheet).reduce((sum, count) => sum + count, 0);

return [{
  json: {
    has_rows_to_delete: blocks.length > 0,
    blocks,
    matched_rows: matchedRows,
    ignored_invalid_dates: ignoredInvalidDateRows.length,
    ignored_invalid_date_rows: ignoredInvalidDateRows,
    by_sheet: bySheet,
    cutoff_iso: new Date(cutoffMs).toISOString(),
    dry_run: cfg.dry_run,
    policy: 'Delete rows matching configured statuses and retention age.',
  },
}];

const plan = $input.first()?.json || {};
const blocks = Array.isArray(plan.blocks) ? plan.blocks : [];
return blocks.map(block => ({
  json: {
    ...block,
    cleanup_cutoff_iso: plan.cutoff_iso,
  },
}));

const plan = $('Build Cleanup Plan').first().json;
return [{
  json: {
    status: 'completed',
    deleted_rows: plan.matched_rows,
    deletion_blocks: plan.blocks.length,
    by_sheet: plan.by_sheet,
    ignored_invalid_dates: plan.ignored_invalid_dates,
    cutoff_iso: plan.cutoff_iso,
  },
}];

const cfg = {
  spreadsheet_id: 'YOUR_GOOGLE_SHEET_ID',
  cv_active_folder_id: 'YOUR_CV_ACTIVE_FOLDER_ID',
  timezone: 'UTC',
  // Keep the same twelve sheet names in every workflow.
  monthly_sheets: ["JANEIRO", "FEVEREIRO", "MARÇO", "ABRIL", "MAIO", "JUNHO", "JULHO", "AGOSTO", "SETEMBRO", "OUTUBRO", "NOVEMBRO", "DEZEMBRO"],
};
if (cfg.spreadsheet_id.startsWith('YOUR_')) throw new Error('Configure spreadsheet_id in Config.');
new Intl.DateTimeFormat('en-US', {timeZone: cfg.timezone});

cfg.workbook_year = new Date().getUTCFullYear(); // Used only for dates without an explicit year.
cfg.age_days = 90;
cfg.target_statuses = ['Mismatch', 'Closed'];
cfg.dry_run = true; // Review the plan before changing to false.
if (!Number.isInteger(cfg.age_days) || cfg.age_days < 1) throw new Error('age_days must be a positive integer.');
return [{json:cfg}];

const rows = [];
for (const range of $json.valueRanges || []) {
 const sheet = String(range.range || '').split('!')[0].replace(/^'|'$/g, '').replaceAll("''", "'");
 for (let i=1; i<(range.values || []).length; i++) {
  const r=range.values[i];
  rows.push({json:{_cleanup_sheet:sheet, row_number:i+1, 'Job ID':r[0], Status:r[1], 'Date Scraped':r[2]}});
 }
}
return rows.length ? rows : [{json:{}}];
